import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.Select;
import com.github.pagehelper.PageException;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    // Attempt to parse the SQL
    Statement stmt;
    try {
        stmt = CCJSqlParserUtil.parse(sql); // Use CCJSqlParserUtil for parsing
    } catch (Exception e) {
        throw new PageException("Failed to parse the SQL. Ensure it's a valid SQL statement!", e);
    }
    if (!(stmt instanceof Select)) {
        throw new PageException("The statement must be a SELECT query for pagination!");
    }

    // Get the SELECT statement for pagination
    Select selectStatement = (Select) stmt;

    // Convert the SELECT into a paginated SQL (Assuming getPageSelect is implemented correctly)
    Select pageSelect = getPageSelect(selectStatement);

    // Convert the Select object back to a string
    String pageSql = pageSelect.toString();

    // Replace placeholders with the actual values, if present
    if (offset != null) {
        pageSql = pageSql.replace(START_ROW, String.valueOf(offset));
    }
    if (limit != null) {
        pageSql = pageSql.replace(PAGE_SIZE, String.valueOf(limit));
    }

    return pageSql;
}

