import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.statement.select.PlainSelect;
import net.sf.jsqlparser.statement.select.Limit;
import com.github.pagehelper.PageException;

public class SqlPageConverter {

    public String convertToPageSql(String sql, Integer offset, Integer limit) {
        // Preprocess the SQL to handle SQL Server specific syntax
        sql = preprocessSql(sql);

        // Attempt to parse the SQL
        Statement stmt;
        try {
            stmt = CCJSqlParserUtil.parse(sql);
        } catch (Exception e) {
            throw new PageException("Failed to parse the SQL. Check for unsupported syntax! SQL: " + sql, e);
        }

        if (!(stmt instanceof Select)) {
            throw new PageException("The statement must be a SELECT query for pagination!");
        }

        // Convert the SELECT statement into a paginated SQL
        Select select = (Select) stmt;
        applyPagination(select, offset, limit);

        return select.toString();
    }

    // Function to preprocess SQL, mainly for SQL Server specific syntax
    private String preprocessSql(String sql) {
        // Remove square brackets around identifiers
        sql = sql.replaceAll("\\[", "").replaceAll("\\]", "");

        // Handle additional SQL Server specific constructs here if necessary

        return sql;
    }

    // Function to apply pagination
    private void applyPagination(Select select, Integer offset, Integer limit) {
        PlainSelect plainSelect = (PlainSelect) select.getSelectBody();

        Limit limitClause = new Limit();
        if (limit != null) {
            limitClause.setRowCount(limit.longValue());
        }
        if (offset != null) {
            limitClause.setOffset(offset.longValue());
        }

        plainSelect.setLimit(limitClause);
    }
}
